#!/usr/bin/env bash
# Vendor sqlfluff's Rust lexer and parser (sqlfluffrs) at one commit.
#
#   vendor/sqlfluffrs/update.sh [<sqlfluff commit>]   (also: just vendor-sqlfluffrs)
#
# sqlfluffrs is not on crates.io, and its dialect grammars are not in git:
# sqlfluffrs_dialects/build.rs generates them with Python (`import sqlfluff`).
# So cogitator vendors the four crates it needs WITH the generated dialects,
# and building cogitator needs neither Python nor the network. Only this
# script does: git, uv and a Python 3.10+ (nix/tooling.nix has both).
#
# What it changes of upstream, and nothing else:
#   - the crates keep their sources; the PyO3 bridge's optional dependencies
#     and features, dev-dependencies, tests and benches are dropped;
#   - sqlfluffrs_dialects loses its build.rs (the sources are generated here);
#   - a workspace manifest of their own (Cargo.toml here), outside
#     cogitator's, holds the versions upstream's workspace declared.
set -euo pipefail

here="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
rev="${1:-$(sed -n 's/^commit = "\(.*\)"$/\1/p' "$here/VENDORED.toml")}"
[ -n "$rev" ] || { echo "usage: $0 <sqlfluff commit>" >&2; exit 2; }
crates=(sqlfluffrs_types sqlfluffrs_dialects sqlfluffrs_lexer sqlfluffrs_parser)

work="$(mktemp -d)"
trap 'rm -rf "$work"' EXIT
git -C "$work" init -q sqlfluff
git -C "$work/sqlfluff" fetch -q --depth 1 https://github.com/sqlfluff/sqlfluff "$rev"
git -C "$work/sqlfluff" checkout -q FETCH_HEAD
full="$(git -C "$work/sqlfluff" rev-parse HEAD)"
date="$(git -C "$work/sqlfluff" log -1 --format=%cs)"

python="${PYTHON:-python3}"
(cd "$work/sqlfluff" && uv run -q --no-project --python "$python" --with ./ \
    python utils/rustify.py build)

up="$work/sqlfluff/sqlfluffrs"
for c in "${crates[@]}"; do
    rm -rf "${here:?}/$c"
    mkdir -p "$here/$c"
    cp -R "$up/$c/src" "$here/$c/src"
    # the manifest, less what needs the PyO3 bridge or a dev build
    awk '
        /^\[dev-dependencies\]/ || /^\[\[bench\]\]/ || /^\[\[test\]\]/ { skip = 1; next }
        /^\[/ { skip = 0 }
        skip { next }
        /^build *=/ { next }
        /optional = true/ { next }
        /^python *=/ { next }
        { print }
    ' "$up/$c/Cargo.toml" > "$here/$c/Cargo.toml"
    printf '\n[lints.rust]\n# the PyO3 bridge (feature "python") is not vendored, and what only it\n# used is dead here; upstream'"'"'s code is not ours to change\nunexpected_cfgs = "allow"\ndead_code = "allow"\n' \
        >> "$here/$c/Cargo.toml"
done

# the workspace's versions, without the bridge's and the benches'
awk '
    /^\[workspace.dependencies\]/ { on = 1; print; next }
    /^\[/ { on = 0 }
    on && /^(pyo3|criterion) *=/ { drop = ($0 ~ /\[ *$/); next }
    drop { if ($0 ~ /^\]/) drop = 0; next }
    on && NF { print }
' "$up/Cargo.toml" > "$work/deps.toml"
{
    echo "# GENERATED by update.sh from sqlfluff $full; do not edit."
    echo "[workspace]"
    echo "resolver = \"2\""
    printf 'members = [%s]\n' "$(printf '"%s", ' "${crates[@]}" | sed 's/, $//')"
    echo
    sed -n '/^\[workspace.package\]/,/^\[/p' "$up/Cargo.toml" | sed '$d'
    cat "$work/deps.toml"
} > "$here/Cargo.toml"

cp "$up/LICENSE.md" "$here/LICENSE.md"
cat > "$here/VENDORED.toml" <<EOF
# Which sqlfluff commit vendor/sqlfluffrs holds; update.sh reads and writes it.
repository = "https://github.com/sqlfluff/sqlfluff"
commit = "$full"
date = "$date"
crates = [$(printf '"%s", ' "${crates[@]}" | sed 's/, $//')]
EOF
echo "vendored sqlfluffrs at $full ($date)"
